import zipfile
import re
import xml.etree.ElementTree as ET

path = "budget.xlsx"

NS = {
    "m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main",
    "r": "http://schemas.openxmlformats.org/officeDocument/2006/relationships",
}

def col_to_idx(ref):
    letters = re.match(r"[A-Z]+", ref).group(0)
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch) - 64)
    return idx - 1  # 0-based

with zipfile.ZipFile(path) as z:
    names = z.namelist()
    print("Archive entries:", names)

    wb = ET.fromstring(z.read("xl/workbook.xml"))
    rels = ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))

    rel_map = {}
    for rel in rels:
        rel_map[rel.get("Id")] = rel.get("Target")

    sheet_names = []
    for sh in wb.find("m:sheets", NS):
        rid = sh.get("{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id")
        sheet_names.append((sh.get("name"), rel_map[rid].lstrip("/")))
    print("Sheets:", sheet_names)

    shared = []
    if "xl/sharedStrings.xml" in names:
        sst = ET.fromstring(z.read("xl/sharedStrings.xml"))
        for si in sst.findall("m:si", NS):
            text = "".join(t.text or "" for t in si.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t"))
            shared.append(text)

    for sheet_name, target in sheet_names:
        path_in_zip = "xl/" + target if not target.startswith("xl/") else target
        print(f"\n=== Sheet: {sheet_name} ===")
        root = ET.fromstring(z.read(path_in_zip))
        sd = root.find("m:sheetData", NS)
        for row in sd.findall("m:row", NS):
            cells = []
            for c in row.findall("m:c", NS):
                ref = c.get("r")
                t = c.get("t")
                v = c.find("m:v", NS)
                val = None
                if v is not None:
                    raw = v.text
                    if t == "s":
                        val = shared[int(raw)]
                    else:
                        val = raw
                elif c.find("m:is", NS) is not None:
                    val = "".join(x.text or "" for x in c.find("m:is", NS).iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t"))
                cells.append((ref, t, val))
            if cells:
                print(row.get("r"), cells)

